-- PAY-005: reservations do not reduce a resident receivable until settlement is recorded.
CREATE TABLE tt_payment_policies(id TEXT PRIMARY KEY,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),version INTEGER NOT NULL,terms TEXT NOT NULL,reference TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenancy_id,version));
CREATE TABLE tt_payments(id TEXT PRIMARY KEY,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),policy_id TEXT NOT NULL REFERENCES tt_payment_policies(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),credit_cents INTEGER NOT NULL CHECK(credit_cents>=0),state TEXT NOT NULL CHECK(state IN ('pending','settled','failed')),payer_kind TEXT NOT NULL CHECK(payer_kind IN ('resident','co_tenant','housing_authority')),payer_id TEXT,payer_name TEXT NOT NULL,method TEXT NOT NULL,received_date TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,snapshot TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TABLE tt_payment_allocations(payment_id TEXT NOT NULL REFERENCES tt_payments(id),charge_id TEXT NOT NULL REFERENCES tt_charges(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),receipt_id TEXT NOT NULL UNIQUE,PRIMARY KEY(payment_id,charge_id));
CREATE TABLE tt_payment_events(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES tt_payments(id),state TEXT NOT NULL,reference TEXT NOT NULL,on_day TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE INDEX tt_payment_lease ON tt_payments(tenancy_id);
CREATE VIEW tt_payment_reserved AS SELECT a.charge_id,SUM(a.amount_cents) AS amount_cents FROM tt_payment_allocations a JOIN tt_payments p ON p.id=a.payment_id WHERE p.state='pending' GROUP BY a.charge_id;
CREATE TRIGGER tt_payment_policy_fixed BEFORE UPDATE ON tt_payment_policies WHEN NOT(EXISTS(SELECT 1 FROM tt_erasure_work WHERE tenancy_id=OLD.tenancy_id) AND NEW.reference=OLD.id AND NEW.id=OLD.id AND NEW.tenancy_id=OLD.tenancy_id AND NEW.version=OLD.version AND NEW.terms=OLD.terms AND NEW.created_by=OLD.created_by AND NEW.created_at=OLD.created_at) BEGIN SELECT RAISE(ABORT,'Payment policy versions are immutable'); END;
